const items = $input.all();
const response = items[0].json;

// Handle various API response shapes
let strategies = [];
if (Array.isArray(response)) {
  strategies = response;
} else if (response.data && Array.isArray(response.data)) {
  strategies = response.data;
} else if (response.strategies && Array.isArray(response.strategies)) {
  strategies = response.strategies;
}

if (strategies.length === 0) {
  return [{
    json: {
      _noStrategies: true,
      report_date: new Date().toISOString().split('T')[0],
      strategies_analyzed: 0,
      total_anti_setups_found: 0,
      by_strategy: [],
      message: 'No active strategies found'
    }
  }];
}

// Return each strategy as a separate item for SplitInBatches
return strategies.map(s => ({
  json: {
    strategy_id: s.id || s.strategy_id,
    strategy_name: s.name || s.strategy_name || s.id || 'Unknown',
    total_strategies: strategies.length
  }
}));

const items = $input.all();
const response = items[0].json;

// Get the strategy info from the loop item (use modern syntax)
const strategyName = $('Loop Over Strategies').first().json.strategy_name;
const strategyId = $('Loop Over Strategies').first().json.strategy_id;

// Parse anti-setup count from response
let antiSetupCount = 0;
let estimatedPnlImpact = '$0';

if (response.anti_setups && Array.isArray(response.anti_setups)) {
  antiSetupCount = response.anti_setups.length;
} else if (typeof response.count === 'number') {
  antiSetupCount = response.count;
} else if (response.results && Array.isArray(response.results)) {
  antiSetupCount = response.results.length;
}

if (response.estimated_pnl_impact) {
  estimatedPnlImpact = response.estimated_pnl_impact;
} else if (response.pnl_impact) {
  estimatedPnlImpact = response.pnl_impact;
}

return [{
  json: {
    strategy: strategyName,
    strategy_id: strategyId,
    anti_setups: antiSetupCount,
    estimated_pnl_impact: estimatedPnlImpact,
    raw_response: response
  }
}];

const items = $input.all();

// Collect all mining results from the loop
const byStrategy = items.map(item => ({
  strategy: item.json.strategy || 'Unknown',
  strategy_id: item.json.strategy_id || 'unknown',
  anti_setups: item.json.anti_setups || 0,
  estimated_pnl_impact: item.json.estimated_pnl_impact || '$0'
}));

const totalAntiSetups = byStrategy.reduce((sum, s) => sum + s.anti_setups, 0);

const report = {
  report_date: new Date().toISOString().split('T')[0],
  strategies_analyzed: byStrategy.length,
  total_anti_setups_found: totalAntiSetups,
  by_strategy: byStrategy,
  generated_at: new Date().toISOString()
};

return [{ json: report }];

